    score += bin_pressure;

    // If this is the only bin that can fit the item, prioritize it to avoid 
    // unnecessary new bin allocation unless the fit is extremely poor.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Discourage opening a new bin (where bin_residual == bin_capacity) 
    // unless the fit in existing bins is truly terrible (high post_residual).
    if bin_residual == bin_capacity {
        // Base cost for opening a new bin is high to force use of existing capacity.
        score = 85.0 + (open_bins_count as f64 * 0.5);
    }

    score
