pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;

    // Base heuristic: Minimize post_residual (Best Fit principle)
    // We add a non-linear penalty for creating "fragmented" space (small residues) 
    // that are unlikely to accommodate the next item.
    let mut score = post;

    // Penalty for creating a bin with a very small residual that is likely to be stranded
    // if the next item is large. We scale this penalty by the lookahead next_item_size.
    if next_item_size > 0 && post < next_item_size as f64 {
        score += (next_item_size as f64 - post).powf(1.5);
    }

    // Dynamic pressure: As the stream progresses, prioritize filling bins more tightly 
    // to avoid leaving too many bins open at the end (the "tail" problem).
    // The term (1.0 - progress) increases the penalty for loose fits early on.
    score += (1.0 - progress) * (post.powf(1.2));

    // If this is the last chance to fit the item in an existing bin, reduce the score
    // to prevent opening a new bin prematurely unless the fit is extremely poor.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Penalty for opening a brand-new bin:
    // We make it harder to open a new bin as the stream progresses, 
    // forcing the algorithm to use existing capacity.
    if bin_residual == bin_capacity {
        score += 35.0 + (progress * 25.0);
    }

    // Interaction with mean_residual: If current bin is significantly emptier than the average,
    // penalize it to encourage consolidation into more efficient bins.
    if bin_residual as f64 > mean_residual {
        score += (bin_residual as f64 - mean_residual) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals (wasted space)
    // but normalize against the mean_residual to avoid fragmentation.
    score += post_residual as f64 * 0.5;

    // 2. Lookahead Integration: If the post_residual is a perfect or near-perfect
    // fit for the next item, heavily reward this bin selection.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward exact matches or tight fits for the next item
            let gap = (post_residual - next_item_size) as f64;
            score -= (100.0 - gap) * 2.5;
        } else {
            // Penalize if this placement prevents the next item from fitting
            score += 50.0;
        }
    }

    // 3. Last-Chance Logic: If this is the only bin that can fit the item, 
    // prioritize it heavily to avoid creating a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // 4. New Bin Threshold: If we are considering a new bin (bin_residual == bin_capacity),
    // only accept it if the current mean_residual is very low (indicating most bins are full).
    if bin_residual == bin_capacity {
        if open_bins_count > 0 && mean_residual > 20.0 {
            score += 150.0; // Discourage new bins if existing ones have space
        } else {
            score += 80.0; // Neutral baseline for opening a new bin
        }
    }

    // 5. Progression Scaling: As the stream nears completion, become more 
    // aggressive about filling existing bins to minimize leftover empty space.
    let progress = step_index as f64 / total_items as f64;
    score += (1.0 - progress) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "orphan" space that is too small for common items.
    // If post_residual is small but not zero, it's often a waste.
    if post_residual > 0 && post_residual < 20 {
        score += 45.0;
    }

    // 2. Lookahead optimization: If the next item fits perfectly into the post_residual,
    // prioritize this bin heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let diff = (post_residual - next_item_size) as f64;
        // Reward closer matches to the next item
        score -= (50.0 / (1.0 + diff));
    }

    // 3. Prevent opening new bins prematurely.
    // If this is a new bin (bin_residual == bin_capacity), penalize it unless
    // the current number of bins is low or no other bins can fit the item.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 60.0;
        }
        // Penalize opening new bins if we are early in the stream
        let progress = step_index as f64 / total_items as f64;
        score += 20.0 * (1.0 - progress);
    }

    // 4. Balance bin usage: favor bins that keep residuals near the mean.
    // This helps prevent fragmentation across many bins.
    let dev_from_mean = (post_residual as f64 - mean_residual).abs();
    score += dev_from_mean * 0.2;

    // 5. Hard constraint: If this is the only bin that fits the item, 
    // force selection by lowering the score significantly.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: lower post_residual is generally better.
    // We prioritize bins where the remaining space is small, but penalize space that is "useless"
    // (e.g., smaller than the smallest likely item, here assumed to be 10).
    if post_residual < 10 {
        score -= 20.0; // Reward tight packing
    }

    // 2. Lookahead coupling: If a bin can fit the next item, reward it.
    // This effectively implements a basic Best-Fit-Lookahead strategy.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 3. Harmonic class alignment: Penalize residuals that create awkward gaps.
    // If post_residual is a multiple of common small item sizes, it's more flexible.
    if post_residual % 10 == 0 {
        score -= 5.0;
    }

    // 4. New Bin Thresholding:
    // If this is a new bin (bin_residual == bin_capacity), penalize it heavily 
    // unless no existing bins can fit the item or the remaining space in existing bins is very poor.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if we have options
            score += 65.0 + (mean_residual * 0.5);
        } else {
            // If no other option, make it neutral
            score = 50.0;
        }
    } else {
        // 5. Open Bin Efficiency:
        // If we have many open bins, penalize creating more free space in them.
        score += (open_bins_count as f64) * 0.2;
    }

    // 6. Progressive tightening: As the stream nears the end, become more aggressive 
    // about filling existing bins to avoid stranded items.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: penalize large residuals (standard Best-Fit)
    // 2. Harmonic penalty: heavily penalize residuals that are small but unusable 
    //    for common item sizes (10-80).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 3. Lookahead integration: 
    // If the next item fits into the current post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 4. Harmonic class bias:
    // If we have many bins open, prioritize filling the tightest bin (Best-Fit).
    // If fitting_bins_count is 1, this is the only bin that can take the item;
    // heavily incentivize this unless it creates a very poor residual.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // 5. New-bin thresholding:
    // Only open a new bin if the current bin_residual is exactly bin_capacity,
    // and even then, only if the mean residual is high enough to suggest 
    // we should be more aggressive in creating space.
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score = 0.0;
        } else {
            // Penalize opening a new bin if we have existing capacity
            score += 65.0 + (mean_residual * 0.5);
        }
    }

    // 6. Non-linear coupling: 
    // Penalize placements that leave a remainder that is a small fraction 
    // of the capacity (unusable slivers).
    let residual_fraction = post_residual as f64 / bin_capacity as f64;
    if residual_fraction > 0.0 && residual_fraction < 0.15 {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for leaving a 'dead zone' that cannot fit common small items (e.g., < 20)
    // We prioritize bins where the post_residual is either 0 (perfect fit) or >= 20.
    if post_residual > 0 && post_residual < 20 {
        score += 40.0 * (20.0 - post_residual as f64);
    }

    // Harmonic influence: favor bins that leave residuals which are multiples of common item sizes
    // This reduces fragmentation by aligning potential future items.
    let harmonic_penalty = (post_residual % 25) as f64;
    score += harmonic_penalty * 0.5;

    // Lookahead logic: if next_item_size is large, avoid bins that leave little room
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Penalize bins that cannot accommodate the next item if they are currently the only option
            score += (next_item_size - post_residual) as f64 * 1.5;
        } else {
            // Reward bins that create a "perfect" landing for the next item
            if (post_residual - next_item_size) < 10 {
                score -= 15.0;
            }
        }
    }

    // Global state awareness: if we have many open bins, penalize opening a new one
    // bin_residual == bin_capacity identifies the "New Bin" candidate.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            // Gradually discourage opening new bins as the stream progresses
            let progress = step_index as f64 / total_items as f64;
            score += 25.0 + (progress * 50.0);
        }
    }

    // Balance the distribution of residuals across all open bins
    // If this bin's residual is significantly lower than the mean, it's a "tight" bin.
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Penalize new bin creation heavily early in the stream, 
    // but allow it if the fit is extremely poor (large post_residual).
    let mut score = post_residual as f64;

    if is_new_bin {
        // Penalty for opening a new bin: base cost + pressure from open bins
        // We scale the penalty by (1.0 - progress) to be more conservative as we near the end
        score = 25.0 + (open_bins_count as f64 * 0.5) + (progress * 15.0);
    } else {
        // Best-fit/First-fit logic with non-linear smoothing
        // We favor bins that leave very small post_residuals (tight fit)
        // or bins that leave large enough residuals to accommodate the next item (lookahead)
        let fit_pressure = (post_residual as f64).powf(1.5);
        score += fit_pressure;

        // Lookahead reward: if the current bin can fit the next item after this one,
        // reduce the score (make it more attractive)
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= (next_item_size as f64) * 0.8;
        }

        // Penalty for creating 'dead space' (residuals too small for common items)
        // If post_residual is < 10, it's likely unusable.
        if post_residual < 10 && post_residual > 0 {
            score += 12.0 * (1.0 - progress);
        }
    }

    // Adjust for scarcity: if this is the only bin that fits, prioritize it strongly
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    }

    score
}

